/bin/bash -lc "cat > internal/cue/validate.go <<'EOF'
package cue

import (
	_ \"embed\"
	\"encoding/json\"
	\"errors\"
	\"fmt\"
	\"io\"
	\"os\"
	\"strconv\"
	\"strings\"

	\"cuelang.org/go/cue\"
	\"cuelang.org/go/cue/ast\"
	\"cuelang.org/go/cue/cuecontext\"
	cueerror \"cuelang.org/go/cue/errors\"
	\"cuelang.org/go/cue/token\"
	\"cuelang.org/go/encoding/yaml\"
)

const (
	jsonFormat = \"json\"
	textFormat = \"text\"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New(\"validation failed\")
)

// Location identifies a position in the original YAML file.
type Location struct {
	File   string "'`json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes a single validation failure.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result contains all errors found while validating a YAML document.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator validates YAML against the embedded CUE schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	c := cuecontext.New()
	v := c.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, fmt.Errorf("compile features schema: %w", err)
	}
	return &FeaturesValidator{cue: c, v: v}, nil
}

// Validate checks a YAML document and returns every CUE validation failure.
func (fv *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	result := Result{Errors: []Error{}}
	f, err := yaml.Extract(file, b)
	if err != nil {
		return result, err
	}

	positions := make(map[string]token.Pos)
	indexDecls(f.Decls, nil, positions)
	v := fv.cue.BuildFile(f, cue.Scope(fv.v))
	v = fv.v.Unify(v)
	if err := v.Validate(); err != nil {
		for _, ce := range cueerror.Errors(err) {
			path := strings.Join(ce.Path(), ".")
			format, args := ce.Msg()
			message := fmt.Sprintf(format, args...)
			if message == "" {
				message = ce.Error()
			}

			// For unknown fields CUE points to the value. The key itself is the
			// offending token; other errors usually point to the invalid value.
			pos := token.NoPos
			if strings.Contains(message, "field not allowed") {
				pos = positions[path]
				message = fmt.Sprintf("field %q not allowed", lastPathPart(path))
			}
			if !pos.IsValid() {
				for _, p := range ce.InputPositions() {
					if p.IsValid() && p.Filename() == file {
						pos = p
						break
					}
				}
			}
			if !pos.IsValid() {
				pos = positions[path]
			}
			if !pos.IsValid() {
				parts := ce.Path()
				for len(parts) > 0 && !pos.IsValid() {
					parts = parts[:len(parts)-1]
					pos = positions[strings.Join(parts, ".")]
				}
			}
			result.Errors = append(result.Errors, Error{
				Path: path, Message: message,
				Location: Location{File: file, Line: pos.Line(), Column: pos.Column()},
			})
		}
		return result, ErrValidationFailed
	}
	return result, nil
}

func lastPathPart(path string) string {
	if i := strings.LastIndexByte(path, '"'.'); i >= 0 {
		return path[i+1:]
	}
	return path
}

func indexDecls(decls []ast.Decl, path []string, positions map[string]token.Pos) {
	for _, decl := range decls {
		if field, ok := decl.(*ast.Field); ok {
			name, _, err := ast.LabelName(field.Label)
			if err "'!= nil {
				continue
			}
			child := append(append([]string(nil), path...), name)
			positions[strings.Join(child, ".")] = field.Label.Pos()
			indexExpr(field.Value, child, positions)
		} else if embed, ok := decl.(*ast.EmbedDecl); ok {
			indexExpr(embed.Expr, path, positions)
		}
	}
}

func indexExpr(expr ast.Expr, path []string, positions map[string]token.Pos) {
	switch x := expr.(type) {
	case *ast.StructLit:
		indexDecls(x.Elts, path, positions)
	case *ast.ListLit:
		for i, elt := range x.Elts {
			child := append(append([]string(nil), path...), strconv.Itoa(i))
			positions[strings.Join(child, ".")] = elt.Pos()
			indexExpr(elt, child, positions)
		}
	}
}

// ValidateBytes validates bytes against the embedded schema.
func ValidateBytes(b []byte) error {
	fv, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	_, err = fv.Validate("", b)
	return err
}

func writeErrorDetails(format string, result Result, w io.Writer) error {
	if format == jsonFormat {
		return json.NewEncoder(w).Encode(result)
	}
	if format != textFormat {
		fmt.Fprintln(w, "Invalid format chosen, defaulting to '"\\\"text\\\" format...\")
	}
	fmt.Fprintln(w, \"❌ Validation failure"'!")
	for _, e := range result.Errors {
		fmt.Fprintf(w, "%s:%d:%d: %s: %s'"\\n\", e.Location.File, e.Location.Line, e.Location.Column, e.Path, e.Message)
	}
	return nil
}

// ValidateFiles checks each file, writes its aggregated result, and signals failure.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	fv, err := NewFeaturesValidator()
	if err "'!= nil {
		return err
	}
	result := Result{Errors: []Error{}}
	for _, file := range files {
		b, err := os.ReadFile(file)
		if err != nil {
			return fmt.Errorf("validation failed: read %s: %w", file, err)
		}
		found, err := fv.Validate(file, b)
		result.Errors = append(result.Errors, found.Errors...)
		if err != nil && !errors.Is(err, ErrValidationFailed) {
			return fmt.Errorf("validation failed: %s: %w", file, err)
		}
	}
	if len(result.Errors) > 0 {
		if err := writeErrorDetails(format, result, dst); err != nil {
			return err
		}
		return ErrValidationFailed
	}
	if format != jsonFormat {
		if format != textFormat {
			fmt.Fprintln(dst, "Invalid format chosen, defaulting to '"\\\"text\\\" format...\")
		}
		fmt.Fprintln(dst, \"✅ Validation success"'!")
	}
	return nil
}
